// Verification support: step definitions for the TodoMVC suite plus the
// Shipshape methodology conformance checks. QM-owned. Step patterns here are
// the canonical strings referenced verbatim by the @planks annotations in
// js/app.js.
const { Given, When, Then, After } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

const STORE_KEY = 'todos-vanillajs';
const WATCHBILL_PATH = 'watchbill.json';
const IMPL_DIRS = ['js'];

// ---------------------------------------------------------------------------
// Methodology conformance checks (verification support, not product behaviour)
// ---------------------------------------------------------------------------
function watchbillShapeCheck() {
  if (!fs.existsSync(WATCHBILL_PATH)) return 'rest';
  let data;
  try {
    data = JSON.parse(fs.readFileSync(WATCHBILL_PATH, 'utf8'));
  } catch (e) {
    return 'violation: invalid JSON';
  }
  const watches = Object.keys(data).filter((k) => /^watch\d+$/.test(k));
  if (watches.length === 0) return 'violation: no watches';
  for (const k of watches) {
    const watch = data[k];
    if (!watch || !Array.isArray(watch.scenarios)) return 'violation: ' + k;
    for (const ref of watch.scenarios) {
      if (typeof ref !== 'string') return 'violation: ' + k + ' entry';
      const isTag = ref.startsWith('@');
      const isRef = /^features\/.*\.feature:/.test(ref);
      if (!isTag && !isRef) return 'violation: ' + ref;
    }
  }
  return 'valid';
}

function walk(dir, cb) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(p, cb);
    else if (entry.isFile()) cb(p);
  }
}

function perturbationQuiescenceCheck() {
  const violations = [];
  for (const dir of IMPL_DIRS) {
    if (!fs.existsSync(dir)) continue;
    walk(dir, (file) => {
      if (fs.readFileSync(file, 'utf8').includes('PERTURBATION')) violations.push(file);
    });
  }
  return violations;
}

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------
Given('the app has loaded', function () {
  this.loadEmpty();
});

Given('the app loads with an empty todo list', function () {
  this.loadEmpty();
});

Given('the app loads with todos:', function (dataTable) {
  const rows = dataTable
    .hashes()
    .map((h) => ({ title: h.title, completed: h.completed === 'true' }));
  this.seedAndLoad(rows);
});

Given('the app loads with todo {string}', function (title) {
  this.loadSingle(title);
});

Given('the working tree has no watchbill file', function () {
  this.moveWatchbillAside();
});

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------
When('{string} is typed into {string} and Enter is pressed', function (text, selector) {
  this.typeAndEnter(selector, text);
});

When('the {string} label is double-clicked', function (title) {
  this.doubleClickLabel(title);
});

When('the {string} todo checkbox is clicked', function (title) {
  this.clickTodoCheckbox(title);
});

When('{string} is clicked', function (selector) {
  this.clickSelector(selector);
});

When('the {string} button is clicked', function (selector) {
  this.clickSelector(selector);
});

When('the {string} todo is marked active', function (title) {
  this.clickTodoCheckbox(title);
});

When('the route is {string}', function (hash) {
  this.setRoute(hash);
});

When('the page is reloaded', function () {
  this.reload();
});

When('{string} is set to {string} and Enter is pressed', function (sel, text) {
  this.setEditValueAndKey(text, 'Enter');
});

When('{string} is set to {string} and Escape is pressed', function (sel, text) {
  this.setEditValueAndKey(text, 'Escape');
});

When('all todos are removed', function () {
  this.removeAllTodos();
});

When('the watchbill-shape conformance check runs', function () {
  this.watchbillResult = watchbillShapeCheck();
});

When('the perturbation-quiescence check scans the implementation directories', function () {
  this.perturbationResult = perturbationQuiescenceCheck();
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------
Then('a todo {string} exists in {string}', function (title, container) {
  const root = this.q(container);
  if (!root) throw new Error('Container not found: ' + container);
  const found = this.ns('li').some((li) => {
    const label = li.querySelector('label');
    return label && label.textContent === title;
  });
  assert.ok(found, 'Todo "' + title + '" not found in ' + container);
});

Then('{string} is empty', function (sel) {
  assert.strictEqual(this.q(sel).value, '');
});

Then('the todo count is {int}', function (n) {
  const strong = this.q('.todo-count strong');
  assert.ok(strong, '.todo-count strong missing');
  assert.strictEqual(strong.textContent, String(n));
});

Then('{string} has focus', function (sel) {
  assert.strictEqual(this.document.activeElement, this.q(sel));
});

Then('the {string} todo has class {string}', function (title, cls) {
  const li = this.findTodoLi(title);
  assert.ok(li, 'Todo not found: ' + title);
  assert.ok(li.classList.contains(cls), 'Todo "' + title + '" missing class "' + cls + '"');
});

Then('its model {string} is {word}', function (key, value) {
  const stored = JSON.parse(this.window.localStorage.getItem(STORE_KEY) || '[]');
  const todo = stored.find((t) => t.title === this.currentTodoTitle);
  assert.ok(todo, 'Stored todo not found: ' + this.currentTodoTitle);
  const expected = value === 'true' ? true : value === 'false' ? false : value;
  assert.strictEqual(todo[key], expected, 'model ' + key);
});

Then('{string} is unchecked', function (sel) {
  assert.strictEqual(this.q(sel).checked, false);
});

Then('{string} is checked', function (sel) {
  assert.strictEqual(this.q(sel).checked, true);
});

Then('its {string} input is focused', function (sel) {
  const li = this.q('.todo-list li.editing') || this.findTodoLi(this.currentTodoTitle);
  assert.ok(li, 'editing li not found');
  assert.strictEqual(this.document.activeElement, li.querySelector(sel));
});

Then('the {string} todo is renamed to {string}', function (orig, newName) {
  this.currentTodoTitle = newName;
  const li = this.findTodoLi(newName);
  assert.ok(li, 'Renamed todo not found: ' + newName);
  assert.strictEqual(li.querySelector('label').textContent, newName);
});

Then('the {string} todo is destroyed', function (title) {
  const li = this.findTodoLi(title);
  assert.ok(!li, 'Todo still present: ' + title);
});

Then('the {string} todo is still named {string}', function (title, name) {
  const li = this.findTodoLi(title);
  assert.ok(li, 'Todo not found: ' + title);
  assert.strictEqual(li.querySelector('label').textContent, name);
});

Then('the {string} ".destroy" button is hidden until the todo is hovered', function (title) {
  const li = this.findTodoLi(title);
  assert.ok(li, 'Todo not found: ' + title);
  const destroy = li.querySelector('.destroy');
  assert.strictEqual(destroy.style.display, 'none', 'destroy should be hidden before hover');
  li.dispatchEvent(new this.window.MouseEvent('mouseenter', { bubbles: true }));
  assert.notStrictEqual(destroy.style.display, 'none', 'destroy should be visible after hover');
});

Then('the {string} section is hidden', function (sel) {
  assert.strictEqual(this.q(sel).style.display, 'none');
});

Then('the {string} shows {string}', function (sel, expected) {
  const el = this.q(sel);
  assert.ok(el, 'Element not found: ' + sel);
  assert.strictEqual(el.innerHTML.trim(), expected);
});

Then('the {string} button is visible', function (sel) {
  const el = this.q(sel);
  assert.ok(el, 'Element not found: ' + sel);
  assert.notStrictEqual(el.style.display, 'none');
});

Then('the {string} button is hidden', function (sel) {
  const el = this.q(sel);
  assert.ok(el, 'Element not found: ' + sel);
  assert.strictEqual(el.style.display, 'none');
});

Then('only active todos are shown', function () {
  const stored = JSON.parse(this.window.localStorage.getItem(STORE_KEY) || '[]');
  const active = stored.filter((t) => !t.completed);
  const lis = this.ns('.todo-list li');
  assert.strictEqual(lis.length, active.length, 'active count mismatch');
  lis.forEach((li) => {
    const title = li.querySelector('label').textContent;
    assert.ok(active.some((t) => t.title === title), 'unexpectedly visible: ' + title);
  });
});

Then('only completed todos are shown', function () {
  const stored = JSON.parse(this.window.localStorage.getItem(STORE_KEY) || '[]');
  const completed = stored.filter((t) => t.completed);
  const lis = this.ns('.todo-list li');
  assert.strictEqual(lis.length, completed.length, 'completed count mismatch');
  lis.forEach((li) => {
    const title = li.querySelector('label').textContent;
    assert.ok(completed.some((t) => t.title === title), 'unexpectedly visible: ' + title);
  });
});

Then('all todos are shown', function () {
  const stored = JSON.parse(this.window.localStorage.getItem(STORE_KEY) || '[]');
  const lis = this.ns('.todo-list li');
  assert.strictEqual(lis.length, stored.length, 'all count mismatch');
});

Then('only the {string} todo remains', function (title) {
  const lis = this.ns('.todo-list li');
  assert.strictEqual(lis.length, 1, 'expected exactly one todo');
  assert.strictEqual(lis[0].querySelector('label').textContent, title);
});

Then('every todo has class {string}', function (cls) {
  const lis = this.ns('.todo-list li');
  assert.ok(lis.length > 0, 'no todos');
  lis.forEach((li) => assert.ok(li.classList.contains(cls), 'todo missing ' + cls));
});

Then('localStorage {string} contains a todo with title {string}', function (key, title) {
  const stored = JSON.parse(this.window.localStorage.getItem(key) || '[]');
  assert.ok(stored.some((t) => t.title === title), 'No todo "' + title + '" in ' + key);
});

Then(/^that stored todo has keys (.+)$/, function (keysStr) {
  const stored = JSON.parse(this.window.localStorage.getItem(STORE_KEY) || '[]');
  const todo = stored[stored.length - 1];
  assert.ok(todo, 'no stored todo');
  const keys = keysStr.split(',').map((k) => k.trim().replace(/^"|"$/g, ''));
  keys.forEach((k) => assert.ok(k in todo, 'missing key ' + k));
});

Then('localStorage {string} does not record the {string} state', function (key, state) {
  const stored = JSON.parse(this.window.localStorage.getItem(key) || '[]');
  stored.forEach((t) => assert.ok(!(state in t), 'todo records ' + state));
});

Then('the {string} filter link has class {string}', function (name, cls) {
  const link = this.ns('.filters a').find((a) => a.textContent.trim() === name);
  assert.ok(link, 'filter link not found: ' + name);
  assert.ok(link.classList.contains(cls), 'filter link ' + name + ' missing ' + cls);
});

Then(/^it reports the deck at rest \(conforms\)$/, function () {
  assert.strictEqual(this.watchbillResult, 'rest', 'expected deck at rest, got: ' + this.watchbillResult);
});

Then('it finds no {string} token', function (token) {
  const violations = this.perturbationResult || [];
  assert.strictEqual(violations.length, 0, token + ' token found in: ' + violations.join(', '));
});

// ---------------------------------------------------------------------------
// Hooks
// ---------------------------------------------------------------------------
After(function () {
  this.restoreWatchbill();
  if (this.window && this.window.close) {
    try { this.window.close(); } catch (e) { /* already closed */ }
  }
});

// Verification support: happy-dom backed world for the TodoMVC behaviour suite.
// QM-owned. Loads the product template into a real DOM realm and drives it
// through public seams, exactly as a browser would.
const { setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const TEMPLATE = fs
  .readFileSync(path.join(__dirname, '..', '..', 'assets', 'app-template.index.html'), 'utf8')
  .replace(/<script[\s\S]*?<\/script>/gi, '');

const APP_CODE = fs.readFileSync(path.join(__dirname, '..', '..', 'js', 'app.js'), 'utf8');
const STORE_KEY = 'todos-vanillajs';
const WATCHBILL_PATH = 'watchbill.json';

class AppWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.currentTodoTitle = null;
    this._watchbillBackup = null;
    this.watchbillResult = null;
    this.perturbationResult = null;
  }

  // Boot a fresh DOM realm with the template and the production app evaluated
  // inside the window's own realm, so document/window/localStorage resolve as
  // the globals the app expects.
  loadApp(todos, urlHash) {
    if (this.window && this.window.close) {
      try { this.window.close(); } catch (e) { /* already closed */ }
    }
    const window = new Window({
      url: 'http://localhost/' + (urlHash || ''),
      settings: { disableJavaScriptFileLoading: true, disableJavaScriptEvaluation: true },
    });
    window.document.write(TEMPLATE);
    if (todos && todos.length) {
      window.localStorage.setItem(STORE_KEY, JSON.stringify(todos));
    } else {
      window.localStorage.removeItem(STORE_KEY);
    }
    window.eval(APP_CODE);
    this.window = window;
    this.document = window.document;
  }

  seedAndLoad(rows) {
    const todos = rows.map((r, i) => ({ id: 'seed-' + (i + 1), title: r.title, completed: r.completed }));
    this.loadApp(todos);
  }

  loadEmpty() {
    this.loadApp([]);
  }

  loadSingle(title) {
    this.loadApp([{ id: 'seed-1', title: title, completed: false }]);
  }

  // --- DOM helpers -------------------------------------------------------
  q(sel) {
    return this.document.querySelector(sel);
  }

  ns(sel) {
    return Array.from(this.document.querySelectorAll(sel));
  }

  findTodoLi(title) {
    return this.ns('.todo-list li').find((li) => {
      const label = li.querySelector('label');
      return label && label.textContent === title;
    }) || null;
  }

  // --- interaction helpers ----------------------------------------------
  clickSelector(sel) {
    const el = this.q(sel);
    if (!el) throw new Error('Element not found: ' + sel);
    el.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }

  clickTodoCheckbox(title) {
    this.currentTodoTitle = title;
    const li = this.findTodoLi(title);
    if (!li) throw new Error('Todo li not found: ' + title);
    li.querySelector('.toggle').dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }

  doubleClickLabel(title) {
    this.currentTodoTitle = title;
    const li = this.findTodoLi(title);
    if (!li) throw new Error('Todo li not found: ' + title);
    li.querySelector('label').dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  }

  typeAndEnter(selector, text) {
    const el = this.q(selector);
    if (!el) throw new Error('Element not found: ' + selector);
    el.value = text;
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
  }

  setEditValueAndKey(text, key) {
    const li = this.q('.todo-list li.editing');
    if (!li) throw new Error('No todo in editing mode');
    const edit = li.querySelector('.edit');
    edit.value = text;
    const code = key === 'Escape' ? 27 : 13;
    edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: code, bubbles: true }));
  }

  setRoute(hash) {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  reload() {
    const raw = this.window.localStorage.getItem(STORE_KEY);
    const todos = raw ? JSON.parse(raw) : [];
    const hash = this.window.location.hash || '';
    this.loadApp(todos, hash);
  }

  removeAllTodos() {
    // Click each destroy button while it is still attached, re-querying after
    // every removal so the click always bubbles to the document listener.
    let destroy;
    while ((destroy = this.q('.todo-list li .destroy'))) {
      destroy.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
    }
  }

  // --- conformance helpers (verification support only) -------------------
  moveWatchbillAside() {
    if (fs.existsSync(WATCHBILL_PATH)) {
      this._watchbillBackup = '.watchbill.qm.bak';
      fs.renameSync(WATCHBILL_PATH, this._watchbillBackup);
    }
  }

  restoreWatchbill() {
    if (this._watchbillBackup && fs.existsSync(this._watchbillBackup)) {
      fs.renameSync(this._watchbillBackup, WATCHBILL_PATH);
      this._watchbillBackup = null;
    }
  }
}

setWorldConstructor(AppWorld);

/* TodoMVC — vanilla JS, no preprocessors.
 * Loaded into a happy-dom window realm during verification (window.eval), so
 * document/window/localStorage resolve as the globals the app expects.
 * Every behaviour-bearing seam carries a @planks annotation naming the exact
 * step-definition pattern it satisfies (see features/support/steps.js).
 */
var ENTER_KEY = 13;
var ESCAPE_KEY = 27;
var STORE_KEY = 'todos-vanillajs';

/** @planks("the app loads with todo {string}") */
function createTodo(title) {
  return { id: uid(), title: title, completed: false };
}

/** @planks("the app loads with todos:") */
/** @planks("the page is reloaded") */
function loadTodos() {
  try {
    return JSON.parse(window.localStorage.getItem(STORE_KEY)) || [];
  } catch (e) {
    return [];
  }
}

/** @planks("localStorage {string} contains a todo with title {string}") */
function saveTodos(todos) {
  window.localStorage.setItem(STORE_KEY, JSON.stringify(todos));
}

var filter = 'all';

/** @planks("the route is {string}") */
function setFilterFromHash() {
  var hash = window.location.hash;
  if (hash === '#/active') filter = 'active';
  else if (hash === '#/completed') filter = 'completed';
  else filter = 'all';
}

/** @planks("{string} is typed into {string} and Enter is pressed") */
function addTodo(title) {
  todos.push(createTodo(title));
  saveTodos(todos);
  render();
}

/** @planks("the {string} todo checkbox is clicked") */
/** @planks("the {string} todo is marked active") */
/** @planks("its model {string} is {word}") */
function toggleTodo(id) {
  todos.forEach(function (t) {
    if (t.id === id) t.completed = !t.completed;
  });
  saveTodos(todos);
  render();
}

/** @planks("{string} is clicked") */
function toggleAll(checked) {
  todos.forEach(function (t) {
    t.completed = checked;
  });
  saveTodos(todos);
  render();
}

/** @planks("the {string} label is double-clicked") */
/** @planks("its {string} input is focused") */
/** @planks("localStorage {string} does not record the {string} state") */
function enterEditMode(li) {
  li.classList.add('editing');
  var edit = li.querySelector('.edit');
  edit.focus();
}

/** @planks("{string} is set to {string} and Enter is pressed") */
/** @planks("the {string} todo is renamed to {string}") */
function commitEdit(edit) {
  var li = edit.closest('li');
  var id = li.dataset.id;
  var value = edit.value.trim();
  li.classList.remove('editing');
  if (!value) {
    removeTodo(id);
  } else {
    todos.forEach(function (t) {
      if (t.id === id) t.title = value;
    });
    saveTodos(todos);
    render();
  }
}

/** @planks("{string} is set to {string} and Escape is pressed") */
/** @planks("the {string} todo is still named {string}") */
function cancelEdit(edit) {
  var li = edit.closest('li');
  li.classList.remove('editing');
  edit.value = edit.dataset.title || edit.value;
  edit.blur();
}

/** @planks("the {string} todo is destroyed") */
/** @planks("only the {string} todo remains") */
function removeTodo(id) {
  todos = todos.filter(function (t) {
    return t.id !== id;
  });
  saveTodos(todos);
  render();
}

/** @planks("the {string} button is clicked") */
function clearCompleted() {
  todos = todos.filter(function (t) {
    return !t.completed;
  });
  saveTodos(todos);
  render();
}

/** @planks("the {string} \".destroy\" button is hidden until the todo is hovered") */
function attachHover(li, destroy) {
  destroy.style.display = 'none';
  li.addEventListener('mouseenter', function () {
    destroy.style.display = 'block';
  });
  li.addEventListener('mouseleave', function () {
    destroy.style.display = 'none';
  });
}

/** @planks("the {string} section is hidden") */
/** @planks("the todo count is {int}") */
/** @planks("the {string} shows {string}") */
/** @planks("the {string} button is visible") */
/** @planks("the {string} button is hidden") */
/** @planks("every todo has class {string}") */
/** @planks("{string} is unchecked") */
/** @planks("{string} is checked") */
/** @planks("the {string} todo has class {string}") */
/** @planks("only active todos are shown") */
/** @planks("only completed todos are shown") */
/** @planks("all todos are shown") */
/** @planks("the {string} filter link has class {string}") */
/** @planks("a todo {string} exists in {string}") */
function render() {
  var list = document.querySelector('.todo-list');
  var main = document.querySelector('#main');
  var footer = document.querySelector('#footer');
  var count = document.querySelector('.todo-count');
  var clearBtn = document.querySelector('.clear-completed');
  var toggleAllEl = document.querySelector('#toggle-all');

  var visible = todos.filter(function (t) {
    if (filter === 'active') return !t.completed;
    if (filter === 'completed') return t.completed;
    return true;
  });

  main.style.display = todos.length === 0 ? 'none' : '';
  footer.style.display = todos.length === 0 ? 'none' : '';

  list.innerHTML = '';
  visible.forEach(function (t) {
    var li = document.createElement('li');
    li.dataset.id = t.id;
    li.className = t.completed ? 'completed' : '';
    li.innerHTML =
      '<div class="view">' +
      '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
      '<label></label>' +
      '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit">';
    li.querySelector('label').textContent = t.title;
    var edit = li.querySelector('.edit');
    edit.value = t.title;
    edit.dataset.title = t.title;
    attachHover(li, li.querySelector('.destroy'));
    list.appendChild(li);
  });

  var activeCount = todos.filter(function (t) {
    return !t.completed;
  }).length;
  var labelWord = activeCount === 1 ? 'item' : 'items';
  count.innerHTML = '<strong>' + activeCount + '</strong> ' + labelWord + ' left';

  var completedCount = todos.length - activeCount;
  clearBtn.style.display = completedCount > 0 ? '' : 'none';

  toggleAllEl.checked = todos.length > 0 && completedCount === todos.length;

  var links = document.querySelectorAll('.filters a');
  for (var i = 0; i < links.length; i++) {
    var a = links[i];
    var href = a.getAttribute('href');
    var selected =
      (href === '#/' && filter === 'all') ||
      (href === '#/active' && filter === 'active') ||
      (href === '#/completed' && filter === 'completed');
    if (selected) a.classList.add('selected');
    else a.classList.remove('selected');
  }
}

/** @planks("the app has loaded") */
/** @planks("{string} has focus") */
function init() {
  var main = document.querySelector('.main');
  if (main && !main.id) main.id = 'main';
  var footer = document.querySelector('.footer');
  if (footer && !footer.id) footer.id = 'footer';

  todos = loadTodos();
  setFilterFromHash();
  render();
  var input = document.querySelector('.new-todo');
  if (input) input.focus();

  var newTodo = document.querySelector('.new-todo');
  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      var value = newTodo.value.trim();
      if (value) {
        addTodo(value);
        newTodo.value = '';
      }
    }
  });

  document.addEventListener('click', function (e) {
    var toggle = e.target.closest('.toggle');
    if (toggle) {
      toggleTodo(toggle.closest('li').dataset.id);
      return;
    }
    var destroy = e.target.closest('.destroy');
    if (destroy) {
