// ---------------------------------------------------------------------------
// Served index page (features/index-page.feature)
//
// Pins the page a real browser opens: a served index.html at the project root,
// built from the human-owned template, carrying the todo structure, and wired
// to the production script js/app.js. These steps assert observable facts about
// the static served file; they do not exercise js/app.js behaviour, so they
// carry no @planks (verification support only).
// ---------------------------------------------------------------------------
function loadServedDoc(relPath) {
  const full = path.join(__dirname, '..', '..', relPath);
  const html = fs.readFileSync(full, 'utf8');
  const window = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true, disableJavaScriptEvaluation: true },
  });
  window.document.write(html);
  return window.document;
}

// Element-tree path signatures (tag#id.class), comments excluded, so a served
// page that is a structural descendant of the template shares every signature.
function structureSignatures(doc) {
  const sigs = new Set();
  function walk(el, parent) {
    const id = el.id ? '#' + el.id : '';
    const cls = Array.from(el.classList).sort().join('.');
    const local = (el.tagName || '').toLowerCase() + id + (cls ? '.' + cls : '');
    const sig = parent ? parent + '>' + local : local;
    sigs.add(sig);
    const children = el.children;
    for (let i = 0; i < children.length; i++) walk(children[i], sig);
  }
  if (doc.documentElement) walk(doc.documentElement, '');
  return sigs;
}

Given('the project root has a real {string} file', function (fileName) {
  const full = path.join(__dirname, '..', '..', fileName);
  assert.ok(fs.existsSync(full), 'Expected a real file at project root: ' + fileName);
  const stat = fs.statSync(full);
  assert.ok(stat.isFile(), fileName + ' exists but is not a regular file');
  assert.ok(stat.size > 0, fileName + ' is an empty file');
  this.servedFileName = fileName;
});

Given('that page is built from the template {string}', function (templatePath) {
  const served = loadServedDoc(this.servedFileName);
  const template = loadServedDoc(templatePath);
  this.servedDoc = served;
  const servedSigs = structureSignatures(served);
  const templateSigs = structureSignatures(template);
  for (const sig of servedSigs) {
    assert.ok(
      templateSigs.has(sig),
      'Served page element "' + sig + '" is absent from the template; page is not built from the template'
    );
  }
});

Then('the page contains the todo input, the todo list section, and the footer', function () {
  const doc = this.servedDoc;
  assert.ok(doc, 'Served page not loaded; preceding step failed');
  assert.ok(doc.querySelector('.new-todo'), 'Page is missing the todo input (.new-todo)');
  assert.ok(doc.querySelector('.todo-list'), 'Page is missing the todo list section (.todo-list)');
  assert.ok(doc.querySelector('.footer'), 'Page is missing the footer (.footer)');
});

Then('the page loads the application script {string}', function (scriptPath) {
  const doc = this.servedDoc;
  assert.ok(doc, 'Served page not loaded; preceding step failed');
  const scripts = Array.from(doc.querySelectorAll('script'));
  const found = scripts.some((s) => s.getAttribute('src') === scriptPath);
  assert.ok(found, 'Page does not load the application script "' + scriptPath + '"');
});

